#!/usr/bin/env node
/*
 * Copies the token block out of the Tolstoy design system into
 * src/design-tokens.css. The design repo stays the source of truth; the
 * generated file is committed so CI and other checkouts do not need it.
 *
 * Usage:
 *   npm run sync:design -- [path/to/design/css/tolstoy.css]
 *   DESIGN_CSS=... npm run sync:design
 */
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const source =
  process.argv[2] ??
  process.env.DESIGN_CSS ??
  "../../nax/design/css/tolstoy.css";
const from = resolve(process.cwd(), source);
const to = resolve(process.cwd(), "src/design-tokens.css");

const css = readFileSync(from, "utf8");
const start = css.indexOf("   2. Tokens");
const end = css.indexOf("   3. Base");
if (start < 0 || end < 0 || end <= start) {
  throw new Error(`Could not find the token section in ${from}`);
}

const opener = css.lastIndexOf("/*", start);
const block = css.slice(opener, end).trimEnd();
if (!block.includes("--background") || !block.includes('[data-theme="dark"]')) {
  throw new Error(`The token section in ${from} does not look right`);
}

writeFileSync(
  to,
  `/* Generated by scripts/sync-design.mjs from ${source}.
   Do not edit by hand; run \`npm run sync:design\` after a design release. */

${block}
`,
);

console.log(`Wrote ${to}`);
